pub(super) fn require(
    image: &VerifiedCubin,
    manifest: &CubinKernelManifest,
) -> Result<(), ServerError> {
    match (image.derived_from(), image.captured_from()) {
        (Some(pin), None) => {
            pin.require_image(image.byte_len(), image.sha256(), image.binary_sm())?
        }
        (None, Some(pin)) => {
            pin.require_image(image.byte_len(), image.sha256(), image.binary_sm())?
        }
        _ => {
            return Err(failure(
                "2B MLP exactly one sealed original image provenance",
            ));
        }
    }
    require_record(
        image.sha256(),
        image.byte_len(),
        image.binary_sm(),
        manifest,
    )
}
fn require_record(
    sha: [u8; 32],
    bytes: usize,
    sm: u8,
    manifest: &CubinKernelManifest,
) -> Result<(), ServerError> {
    let rules = RULES
        .as_ref()
        .ok_or_else(|| failure("2B MLP complete ABI table not materialized"))?;
    let record = (sha, bytes, sm, super::attention_policy::digest(manifest));
    if !matches_rule(rules, record) {
        return Err(failure(
            "2B MLP exact original image/geometry/scalar/stride/pointer/access ABI",
        ));
    }
    Ok(())
}
fn matches_rule(rules: &[Rule], record: Rule) -> bool {
    rules.contains(&record)
}

